const COAT = '#c8985c'
const HEART = '#e87887'
const SEC = 1000
const MIN = 60 * SEC
const SKIN_PANE = 'zsemle-skins'
const WEEK_PANE = 'zsemle-week'
const DAY = 86400000

function help(): string {
